<?php
require_once __DIR__ . '/config/config.php'; require_once __DIR__ . '/config/helpers.php'; require_login();
$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM farmers WHERE id=?');$s->execute([$id]);$f=$s->fetch();if(!$f) redirect('farmers.php');
$s=$pdo->prepare('SELECT * FROM bills WHERE farmer_id=? ORDER BY id DESC');$s->execute([$id]);$bills=$s->fetchAll();$total=array_sum(array_map(fn($b)=>(float)$b['total_amount'],$bills));
$pageTitle='Farmer Details';include __DIR__.'/includes/header.php';
?><div class="form-grid"><div class="card"><div class="stat-label">Farmer</div><div class="stat-value" style="font-size:22px"><?=e($f['name'])?></div><p><?=e($f['phone'])?></p><p><?=nl2br(e($f['address']))?></p><p><strong><?=e($f['district'])?></strong></p><div class="actions"><a class="btn btn-primary" href="farmer_edit.php?id=<?=$f['id']?>">Edit Farmer</a><a class="btn btn-secondary" href="bill_create.php?farmer_id=<?=$f['id']?>">New Bill</a></div></div><div class="card"><div class="stat-label">Purchase Summary</div><div class="stat-value" style="font-size:22px"><?=money($total)?></div><p><?=count($bills)?> bills</p></div></div><div class="section-head"><h2>Purchase History</h2></div><div class="table-wrap"><table><thead><tr><th>Bill</th><th>Date</th><th>Gross Weight</th><th>Net/Remainder</th><th>Payment</th><th>Action</th></tr></thead><tbody><?php foreach($bills as $b): ?><tr><td><?=e($b['bill_number'])?></td><td><?=e(date('d M Y',strtotime($b['bill_date'])))?></td><td><?=number_format($b['gross_weight_kg'],2)?> kg</td><td><?=number_format($b['net_weight_kg'],2)?> kg</td><td><?=money($b['total_amount'])?></td><td><a class="btn btn-light" href="bill_view.php?id=<?=$b['id']?>">View</a></td></tr><?php endforeach;?><?php if(!$bills):?><tr><td colspan="6" class="empty">No purchase history.</td></tr><?php endif;?></tbody></table></div><?php include __DIR__.'/includes/footer.php'; ?>
